ga2w(){return"\u0623\u0646\u0645\u0627\u0637 \u062c\u0627\u0647\u0632\u0629 \u0644\u0623\u0646\u0648\u0627\u0639 \u062d\u0627\u0644\u0627\u062a \u062a\u064f\u0628\u0646\u0649 \u0645\u0639\u064b\u0627 \u062f\u0627\u0626\u0645\u064b\u0627 (\u0645\u062b\u0644 \u0627\u0644\u062f\u0639\u0627\u0645\u0629 \u0648\u0627\u0644\u062a\u0627\u062c) \u2014 \u0627\u062e\u062a\u0631\u0647\u0627 \u0641\u064a \u062d\u0627\u0644\u0629 \u062c\u062f\u064a\u062f\u0629 \u0644\u0625\u0646\u0634\u0627\u0621 \u0643\u0644 \u0646\u0648\u0639 \u062f\u0641\u0639\u0629 \u0648\u0627\u062d\u062f\u0629."},
ga23(){return"\u0627\u0644\u0633\u0645\u0627\u062d \u0628\u0627\u0644\u0627\u062e\u062a\u064a\u0627\u0631 \u0627\u0644\u062d\u0631"},
ga24(){return"\u0627\u0644\u0633\u0645\u0627\u062d \u0623\u064a\u0636\u064b\u0627 \u0644\u0634\u0627\u0634\u0629 \u062d\u0627\u0644\u0629 \u062c\u062f\u064a\u062f\u0629 \u0628\u0627\u062e\u062a\u064a\u0627\u0631 \u0623\u064a \u0645\u062c\u0645\u0648\u0639\u0629 \u0645\u0646 \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0646\u0634\u0637\u0629 \u0645\u0628\u0627\u0634\u0631\u0629\u060c \u0643\u0644 \u0646\u0648\u0639 \u0645\u0639 \u0645\u0627\u062f\u062a\u0647/\u062f\u0631\u062c\u0629 \u0644\u0648\u0646\u0647 \u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a\u0629 \u0623\u062f\u0646\u0627\u0647 \u2014 \u0648\u0644\u064a\u0633 \u0641\u0642\u0637 \u0627\u0644\u0623\u0646\u0645\u0627\u0637 \u0627\u0644\u0645\u062d\u0641\u0648\u0638\u0629 \u0623\u0639\u0644\u0627\u0647."},
gIc(){return"\u0627\u0644\u0627\u0641\u062a\u0631\u0627\u0636\u064a \u0644\u0647\u0630\u0627 \u0627\u0644\u0646\u0648\u0639 \u2014 \u064a\u064f\u0633\u062a\u062e\u062f\u0645 \u0623\u0648\u0644\u064b\u0627 \u0639\u0646\u062f \u0627\u062e\u062a\u064a\u0627\u0631 \u0647\u0630\u0627 \u0627\u0644\u0646\u0648\u0639 \u0641\u064a \u062d\u0627\u0644\u0629 \u062c\u062f\u064a\u062f\u0629"},
gI1(){return"\u0625\u0636\u0627\u0641\u0629 \u0645\u062c\u0645\u0648\u0639\u0629"},
ga2O(){return"\u062a\u0639\u062f\u064a\u0644 \u0627\u0644\u0645\u062c\u0645\u0648\u0639\u0629"},
ga3w(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u0645\u062c\u0645\u0648\u0639\u0627\u062a \u0628\u0639\u062f."},
ga3q(){return"\u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0627\u0644\u0623\u0633\u0639\u0627\u0631"},
ga3p(){return'\u0639\u0644\u0627\u0645\u0627\u062a \u0627\u062e\u062a\u064a\u0627\u0631\u064a\u0629 \u0645\u062b\u0644 "\u0639\u0627\u062f\u064a"/"\u0645\u0645\u064a\u0632" \u064a\u0645\u0643\u0646 \u0623\u0646 \u062a\u062d\u0645\u0644\u0647\u0627 \u0627\u0644\u0645\u0627\u062f\u0629 \u2014 \u0635\u0646\u0651\u0641 \u0645\u0627\u062f\u062a\u064a\u0646 \u0623\u0648 \u0623\u0643\u062b\u0631 \u0644\u0646\u0641\u0633 \u0646\u0648\u0639 \u0627\u0644\u062d\u0627\u0644\u0629 \u0628\u0634\u0643\u0644 \u0645\u062e\u062a\u0644\u0641 \u0644\u062a\u0642\u062f\u064a\u0645 \u0642\u0627\u0626\u0645\u0629 \u0623\u0633\u0639\u0627\u0631 \u062b\u0627\u0646\u064a\u0629 \u062f\u0648\u0646 \u062a\u0643\u0631\u0627\u0631 \u0646\u0648\u0639 \u0627\u0644\u062d\u0627\u0644\u0629 \u0646\u0641\u0633\u0647.'},
gI6(){return"\u0625\u0636\u0627\u0641\u0629 \u0645\u0633\u062a\u0648\u0649"},
ga2S(){return"\u062a\u0639\u062f\u064a\u0644 \u0627\u0644\u0645\u0633\u062a\u0648\u0649"},
ga3x(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u0645\u0633\u062a\u0648\u064a\u0627\u062a \u0628\u0639\u062f \u2014 \u062a\u0639\u0645\u0644 \u0627\u0644\u0645\u0648\u0627\u062f \u062a\u0645\u0627\u0645\u064b\u0627 \u0643\u0645\u0627 \u0643\u0627\u0646\u062a \u062d\u062a\u0649 \u062a\u0636\u064a\u0641 \u0648\u0627\u062d\u062f\u064b\u0627."},
