gamw(){return"\u0631\u0645\u0632 \u062c\u062f\u064a\u062f"},
amo(a){return"\u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u0648\u0627\u0631\u062f\u0629 \u0645\u0646 \u0627\u0644\u0628\u0648\u062a \u062a\u064f\u0633\u062c\u064e\u0651\u0644 \u0628\u0627\u0633\u0645 "+a+"."},
gamr(){return"\u0641\u0635\u0644 \u0627\u0644\u0628\u0648\u062a"},
