gamF(){return"\u0626\u06d5\u0645 \u0628\u06d5\u0633\u062a\u06d5\u0631\u06d5 \u0628\u06c6 \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc\u06cc\u06d5\u06a9\u06d5 \u0628\u0646\u06ce\u0631\u06d5. \u0644\u06d5 \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645\u062f\u0627 \u062f\u06d5\u06cc\u06a9\u0627\u062a\u06d5\u0648\u06d5 \u0648 \u06cc\u06d5\u06a9 \u062c\u0627\u0631 Start \u062f\u0627\u062f\u06d5\u06af\u0631\u06ce\u062a. \u062a\u06d5\u0646\u0647\u0627 \u06cc\u06d5\u06a9 \u062c\u0627\u0631 \u0648 \u0644\u06d5 \u0645\u0627\u0648\u06d5\u06cc \u0662\u0664 \u06a9\u0627\u062a\u0698\u0645\u06ce\u0631\u062f\u0627 \u06a9\u0627\u0631 \u062f\u06d5\u06a9\u0627\u062a."},
gamE(){return"\u06cc\u0627\u0646\u060c \u0628\u06c6 \u0626\u06d5\u0648\u06d5\u06cc \u0647\u06d5\u0645\u0648\u0648 \u0626\u06d5\u0648 \u06a9\u0627\u063a\u06d5\u0632\u0627\u0646\u06d5 \u0628\u0628\u06cc\u0646\u06cc\u062a \u06a9\u06d5 \u062f\u06d5\u06cc\u0646\u06ce\u0631\u06cc\u062a: \u06af\u0631\u0648\u0648\u067e\u06ce\u06a9\u06cc \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645 \u0644\u06d5\u06af\u06d5\u06b5 \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc\u06cc\u06d5\u06a9\u06d5 \u062f\u0631\u0648\u0633\u062a \u0628\u06a9\u06d5\u060c \u067e\u0627\u0634\u0627\u0646 \u0626\u06d5\u0645 \u0628\u06d5\u0633\u062a\u06d5\u0631\u06d5 \u0628\u06a9\u06d5\u0631\u06d5\u0648\u06d5 \u0648 \u0626\u06d5\u0648 \u06af\u0631\u0648\u0648\u067e\u06d5 \u0647\u06d5\u06b5\u0628\u0698\u06ce\u0631\u06d5. \u06a9\u0627\u063a\u06d5\u0632\u06d5\u06a9\u0627\u0646 \u0628\u06c6 \u0647\u06d5\u0631\u062f\u0648\u0648\u06a9\u062a\u0627\u0646 \u0644\u06d5 \u06af\u0631\u0648\u0648\u067e\u06d5\u06a9\u06d5\u062f\u0627 \u062f\u06ce\u0646. \u062a\u06d5\u0646\u0647\u0627 \u06cc\u06d5\u06a9\u06ce\u06a9 \u0644\u06d5\u0645 \u062f\u0648\u0648 \u0628\u06d5\u0633\u062a\u06d5\u0631\u06d5 \u0628\u06d5\u06a9\u0627\u0631\u0628\u0647\u06ce\u0646\u06d5."},
amH(a,b){return a+" \xb7 \u0686\u0627\u0648\u06d5\u0695\u06ce\u06cc Start (\u0628\u06d5\u0633\u062a\u06d5\u0631\u06d5\u06a9\u06d5 \u062a\u0627 "+b+" \u06a9\u0627\u0631 \u062f\u06d5\u06a9\u0627\u062a)"},
