gT7(){return"\u0646\u0627\u06a4\u06ce \u0644\u06cc\u0633\u062a\u06ce (\u0626\u0627\u0631\u06d5\u0632\u0648\u0648\u0645\u06d5\u0646\u062f\u0627\u0646\u06d5)"},
gT3(){return"\u062a\u06d5\u0645\u0627\u0645 \u0628\u0648\u0648"},
gT5(){return"\u0646\u06cc\u0634\u0627\u0646\u06a9\u0631\u0646 \u0648\u06d5\u06a9\u0648 \u062a\u06d5\u0645\u0627\u0645\u0628\u0648\u0648"},
gT6(){return"\u06a4\u06d5\u06a9\u0631\u0646\u06d5\u06a4\u06d5"},
gT1(){return"\u06a4\u06cc \u0644\u06cc\u0633\u062a\u06ce \u0698\u06ce\u0628\u0628\u06d5\u061f"},
gT0(){return"\u0626\u06d5\u06a4\u06d5 \u0644\u06cc\u0633\u062a\u06ce \u0648 \u0647\u06d5\u0645\u06cc \u062a\u0634\u062a\u06ce\u0646 \u062a\u06ce\u062f\u0627 \u0698\u06ce\u062f\u0628\u06d5. \u0646\u0627\u0634\u06ce\u062a \u067e\u0627\u0634\u06af\u06d5\u0632 \u0628\u06cc\u062a\u06d5\u06a4\u06d5."},
T4(a){var s=null
return A.aB(a,s,this.a,s,"1 \u062f\u0627\u0646\u06d5",""+a+" \u062f\u0627\u0646\u06d5",s,s)},
gEQ(){return"\u06a9\u0627\u0644\u0627"},
gTa(){return"\u0628\u0695\u06ce \u067e\u06ce\u062f\u06a4\u06cc"},
